// Setup: register functional interceptors
bootstrapApplication(AppComponent, {
  providers: [
    provideHttpClient(
      withInterceptors([authInterceptor, errorInterceptor, loadingInterceptor])
    )
  ]
});

// Auth interceptor: add Bearer token
const authInterceptor: HttpInterceptorFn = (req, next) => {
  const auth = inject(AuthService);
  const token = auth.getToken();
  if (!token) return next(req);
  return next(req.clone({
    setHeaders: { Authorization: \`Bearer \${token}\` }
  }));
};

// Error interceptor: handle 401 (token refresh) and 403 (redirect)
const errorInterceptor: HttpInterceptorFn = (req, next) => {
  const auth = inject(AuthService);
  const router = inject(Router);
  return next(req).pipe(
    catchError((err: HttpErrorResponse) => {
      if (err.status === 401) return auth.refreshToken().pipe(
        switchMap(token => next(req.clone({ setHeaders: { Authorization: \`Bearer \${token}\` } })))
      );
      if (err.status === 403) router.navigate(['/forbidden']);
      return throwError(() => err);
    })
  );
};

// Loading interceptor: global spinner via signal
const loadingInterceptor: HttpInterceptorFn = (req, next) => {
  const loader = inject(LoadingService);
  loader.increment();
  return next(req).pipe(
    finalize(() => loader.decrement())
  );
};

// HttpContext: skip auth for specific requests
const SKIP_AUTH = new HttpContextToken<boolean>(() => false);
// In service:
this.http.get('/public/data', { context: new HttpContext().set(SKIP_AUTH, true) });
// In interceptor:
if (req.context.get(SKIP_AUTH)) return next(req);

// Retry with backoff using RxJS retry operator
this.http.get('/api/data').pipe(
  retry({ count: 3, delay: (err, retryCount) => timer(retryCount * 1000) })
);
